targets = ["src/a.txt", "src/nested/b.txt"]
for p in targets:
    repo.edit(p, "legacy_flag", "modern_flag", all = True)

# Verify: read back all files, confirm src replaced and docs untouched
after = {}
for p in ["docs/history.txt", "src/a.txt", "src/nested/b.txt", "src/untouched.txt"]:
    after[p] = repo.read(p)

remaining = repo.search("legacy_flag", glob = "**")
modern = repo.search("modern_flag", glob = "**")

return {
    "after": after,
    "remaining_legacy_flag": [(h.path, h.line, h.text) for h in remaining],
    "modern_flag_hits": [(h.path, h.line, h.text) for h in modern],
    "diff": repo.diff(),
}
